CREATE TYPE "RecordStatus" AS ENUM ('ACTIVE','DISABLED','ARCHIVED');
CREATE TYPE "ExpeditionStatus" AS ENUM ('QUEUED','GENERATING','COMPLETED','FAILED');
CREATE TYPE "JobStatus" AS ENUM ('QUEUED','PROCESSING','COMPLETED','FAILED');
CREATE TYPE "ImageStatus" AS ENUM ('PENDING','PROCESSING','COMPLETED','FAILED');
CREATE TYPE "Rarity" AS ENUM ('COMMON','RARE','EPIC','LEGENDARY','MYTHIC');
CREATE TYPE "AnalysisStatus" AS ENUM ('QUEUED','PROCESSING','COMPLETED','FAILED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"walletAddress" VARCHAR(42) UNIQUE NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"lastLoginAt" TIMESTAMP(3));
CREATE TABLE "WalletNonce" ("id" TEXT PRIMARY KEY,"walletAddress" VARCHAR(42) NOT NULL,"nonceHash" TEXT UNIQUE NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"consumedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Civilization" ("id" TEXT PRIMARY KEY,"slug" TEXT UNIQUE NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"imageUrl" TEXT,"status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Region" ("id" TEXT PRIMARY KEY,"slug" TEXT UNIQUE NOT NULL,"civilizationId" TEXT NOT NULL REFERENCES "Civilization"("id") ON DELETE RESTRICT,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"difficulty" TEXT NOT NULL,"imageUrl" TEXT,"unlockRequirement" JSONB NOT NULL,"discoveryPool" JSONB NOT NULL,"status" "RecordStatus" NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE "Expedition" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"regionId" TEXT NOT NULL REFERENCES "Region"("id") ON DELETE RESTRICT,"status" "ExpeditionStatus" NOT NULL DEFAULT 'QUEUED',"rarity" "Rarity","resultRelicId" TEXT UNIQUE,"idempotencyKey" TEXT NOT NULL,"randomnessCommitment" TEXT,"randomnessAudit" JSONB,"rarityConfigVersion" TEXT,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"errorCode" TEXT,UNIQUE("userId","idempotencyKey"));
CREATE TABLE "Relic" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"expeditionId" TEXT UNIQUE NOT NULL REFERENCES "Expedition"("id") ON DELETE RESTRICT,"civilizationId" TEXT NOT NULL REFERENCES "Civilization"("id") ON DELETE RESTRICT,"regionId" TEXT NOT NULL REFERENCES "Region"("id") ON DELETE RESTRICT,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"rarity" "Rarity" NOT NULL,"material" TEXT NOT NULL,"energySignature" TEXT NOT NULL,"description" TEXT NOT NULL,"lore" TEXT NOT NULL,"imageUrl" TEXT,"imageStatus" "ImageStatus" NOT NULL DEFAULT 'PENDING',"metadataVersion" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "Expedition" ADD CONSTRAINT "Expedition_resultRelicId_fkey" FOREIGN KEY ("resultRelicId") REFERENCES "Relic"("id") ON DELETE SET NULL;
CREATE TABLE "RelicAnalysis" ("id" TEXT PRIMARY KEY,"relicId" TEXT NOT NULL REFERENCES "Relic"("id") ON DELETE CASCADE,"status" "AnalysisStatus" NOT NULL DEFAULT 'QUEUED',"provider" TEXT,"model" TEXT,"reportJson" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3));
CREATE TABLE "UserProgress" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"civilizationId" TEXT NOT NULL REFERENCES "Civilization"("id") ON DELETE RESTRICT,"discoveryCount" INTEGER NOT NULL DEFAULT 0,"archiveProgress" DECIMAL(5,2) NOT NULL DEFAULT 0,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("userId","civilizationId"));
CREATE TABLE "AiJob" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"relicId" TEXT REFERENCES "Relic"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"status" "JobStatus" NOT NULL DEFAULT 'QUEUED',"attempts" INTEGER NOT NULL DEFAULT 0,"errorCode" TEXT,"dedupeKey" TEXT UNIQUE NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SystemConfig" ("key" TEXT PRIMARY KEY,"value" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "WalletNonce_walletAddress_expiresAt_idx" ON "WalletNonce"("walletAddress","expiresAt");
CREATE INDEX "Expedition_userId_status_startedAt_idx" ON "Expedition"("userId","status","startedAt");
CREATE INDEX "Relic_userId_createdAt_idx" ON "Relic"("userId","createdAt");
CREATE INDEX "Relic_civilizationId_rarity_idx" ON "Relic"("civilizationId","rarity");
CREATE INDEX "UserProgress_civilizationId_discoveryCount_idx" ON "UserProgress"("civilizationId","discoveryCount");
CREATE INDEX "AiJob_status_createdAt_idx" ON "AiJob"("status","createdAt");
